tools.example:
data = Table[Sin[2 Pi 5 t], {t, 0, 1 - 1/128, 1/128}];
spec = Fourier[data];
spec[[20 ;; -20]] = 0;
ListLinePlot[Re[InverseFourier[spec]]]

data = Table[Exp[-t] Sin[10 t], {t, 0, 5, 0.02}];
coeffs = FourierDCT[data, 2];
ListLinePlot[coeffs, PlotRange -> All]

kernel = ConstantArray[1/5, 5];
noisy = Table[Sin[t] + RandomReal[{-0.3, 0.3}], {t, 0, 10, 0.05}];
ListLinePlot[{noisy, ListConvolve[kernel, noisy, {1, -1}, 0]}]

data = Table[Sin[2 Pi 50 t] + 0.3 Sin[2 Pi 120 t] + RandomReal[{-0.2, 0.2}],
  {t, 0, 2, 1/1000}];
Periodogram[data, SampleRate -> 1000, PlotRange -> All]

data = Table[Sin[2 Pi 50 t], {t, 0, 1, 1/512}];
spec = PeriodogramArray[data];
Position[spec, Max[spec]]

data = Table[Sin[2 Pi 50 t], {t, 0, 1, 1/1000}];
stft = SpectrogramArray[data, 256, 64];
Dimensions[stft]

audio = AudioGenerator["Pink", 1];
stft = ShortTimeFourier[audio];
InverseShortTimeFourier[stft]

data = Table[Sin[2 Pi t] + 0.2 RandomReal[], {t, 0, 4, 1/256}];
dwd = DiscreteWaveletTransform[data, DaubechiesWavelet[4], 4];
WaveletListPlot[dwd]

chirp = Table[Sin[2 Pi (2 + 20 t) t], {t, 0, 4, 1/512}];
cwt = ContinuousWaveletTransform[chirp, GaborWavelet[6]];
WaveletScalogram[cwt]

data = Table[Sin[2 Pi t] + 0.3 RandomReal[], {t, 0, 4, 1/256}];
dwd = DiscreteWaveletTransform[data, DaubechiesWavelet[4], 3];
thr = WaveletThreshold[dwd];
ListLinePlot[{data, InverseWaveletTransform[thr]}]

cwt = ContinuousWaveletTransform[Table[Sin[2 Pi 8 t] + UnitStep[t - 2],
   {t, 0, 4, 1/256}]];
WaveletScalogram[cwt, ColorFunction -> "Rainbow"]

dwd = DiscreteWaveletTransform[Table[Sin[2 Pi t], {t, 0, 4, 1/256}],
  HaarWavelet[], 4];
WaveletListPlot[dwd, Filling -> Axis]

k = SavitzkyGolayMatrix[{6}, 3];
noisy = Table[Exp[-(t - 5)^2] + RandomReal[{-0.05, 0.05}], {t, 0, 10, 0.05}];
ListLinePlot[{noisy, ListConvolve[k, noisy, {1, -1}, 0]}]

data = Table[(1 + 0.5 Sin[2 Pi t]) Sin[2 Pi 30 t], {t, 0, 2, 1/500}];
env = Abs[data + I HilbertFilter[data, 100]];
ListLinePlot[{data, env}]
